import re

def eval_expression(expr: str) -> float:
    """
    Computes the mathematical expression `expr`, respecting the order of operations,
    parentheses, and negative numbers. Raises ZeroDivisionError if division by zero occurs.
    """
    # Tokenize the expression using regex to handle numbers, operators, and parentheses
    # This regex captures integers/floats, negative signs (contextually), and operators.
    token_pattern = re.compile(r'\s*(?:([0-9]+\.?[0-9]*|\.[0-9]+)|([+\-*/()]))')

    tokens = []
    last_token_type = 'OP'  # Used to determine if a '-' is unary (negative) or binary (subtraction)

    pos = 0
    while pos < len(expr):
        match = token_pattern.match(expr, pos)
        if not match:
            if expr[pos].isspace():
                pos += 1
                continue
            raise ValueError(f"Invalid character in expression: '{expr[pos]}'")

        pos = match.end()
        num_str, op_str = match.groups()

        if num_str is not None:
            tokens.append(float(num_str))
            last_token_type = 'NUM'
        else:
            # Handle unary minus for negative numbers
            if op_str == '-' and (last_token_type == 'OP' or last_token_type == 'LPAR'):
                # Peek ahead or just treat the next number as negative
                # A simple way is to parse the next token as a negative number
                next_match = token_pattern.match(expr, pos)
                if next_match and next_match.groups()[0] is not None:
                    tokens.append(-float(next_match.groups()[0]))
                    pos = next_match.end()
                    last_token_type = 'NUM'
                    continue

            tokens.append(op_str)
            if op_str == ')':
                last_token_type = 'RPAR'
            elif op_str == '(':
                last_token_type = 'LPAR'
            else:
                last_token_type = 'OP'

    # Shunting-yard algorithm to convert infix to Postfix (RPN)
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output_queue = []
    operator_stack = []

    for token in tokens:
        if isinstance(token, (int, float)):
            output_queue.append(token)
        elif token in precedence:
            while (operator_stack and operator_stack[-1] in precedence and
                   precedence[operator_stack[-1]] >= precedence[token]):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack and operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            if not operator_stack:
                raise ValueError("Mismatched parentheses")
            operator_stack.pop() # Remove '('

    while operator_stack:
        op = operator_stack.pop()
        if op in ('(', ')'):
            raise ValueError("Mismatched parentheses")
        output_queue.append(op)

    # Evaluate RPN
    eval_stack = []
    for token in output_queue:
        if isinstance(token, (int, float)):
            eval_stack.append(token)
        else:
            if len(eval_stack) < 2:
                raise ValueError("Invalid expression")
            b = eval_stack.pop()
            a = eval_stack.pop()

            if token == '+':
                eval_stack.append(a + b)
            elif token == '-':
                eval_stack.append(a - b)
            elif token == '*':
                eval_stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                eval_stack.append(a / b)

    if len(eval_stack) != 1:
        raise ValueError("Invalid expression")

    result = eval_stack[0]
    # Return as int if it's a whole number, otherwise float
    return int(result) if result.is_integer() else result
